import{_ as a,c as o,o as r,ae as t}from"./chunks/framework.Ck3L_38O.js";const b=JSON.parse('{"title":"주택청약 시 알아야할 것들","description":"","frontmatter":{"title":"주택청약 시 알아야할 것들","date":"2025-04-25T23:00+09:00","tags":["민영주택청약","생애최초 특별공급"]},"headers":[],"relativePath":"posts/housing.md","filePath":"posts/housing.md","lastUpdated":1759329303000}'),l={name:"posts/housing.md"};function c(d,e,i,n,p,h){return r(),o("div",null,[...e[0]||(e[0]=[t('<p>최근 거주지역의 민영주택청약에 생애최초 특별공급으로 신청하여 서류 검수와 계약 체결을 진행하고 있습니다. 주택청약 시 요구 조건과 신청 기준에 따른 서류는 청약자가 모두 알아서 확인하고 준비해야만 합니다. 청약 신청 시 부적격 조건을 사전에 확인하지 못하고 당첨된 이후에 제출된 서류를 통해 부적격 여부를 판단합니다. 매년 꽤 많은 사람들이 <a href="https://www.dailiang.co.kr/news/articleView.html?idxno=228407" target="_blank" rel="noreferrer">주택청약 당첨 뒤 부적격 처리</a>된다고 합니다. 부적격 처리되더라도 청약통장이 사라지는건 아니지만 일정 기간 청약 기회가 제한됩니다.</p><p>민영주택청약의 <a href="https://kbthink.com/main/asset-management/wealth-manage-tip/kbthink-original/202411/first-place.html" target="_blank" rel="noreferrer">일반공급 1순위</a>는 해당지역 그리고 기타지역 순서대로 기회가 주어지면서 주택전용면적에 따라 가점제와 추첨제로 진행됩니다. 이때, 가장 많이 부적격 사례가 발생하는게 <a href="https://blog.toss.im/article/housing-5" target="_blank" rel="noreferrer">주택청약 신청 시 입력한 가점</a>으로 당첨과 서류에 의해 확인되는 가점이 다른 경우에 해당된다고 합니다. 그런데 저는 일반공급이 아닌 <code>생애최초 특별공급</code>으로 신청했습니다.</p><h4 id="생애최초-특별공급" tabindex="-1">생애최초 특별공급 <a class="header-anchor" href="#생애최초-특별공급" aria-label="Permalink to &quot;생애최초 특별공급&quot;">​</a></h4><p>일반공급 1순위 해당지역이 아닌 생애최초 특별공급으로 신청하게 된 이유에는 <code>무주택기간이 길지 않으며 부양가족이 없기 때문에 가점제로 당첨될 가능성은 적다</code>고 판단되기 때문입니다. 그리고 현재 주택을 보유하고 있는 세대주인 아버지가 만 60세 이상으로 주택청약 시에는 무주택 조건이 되면서 <code>무주택세대구성원으로써 신청할 수 있는 공고</code>였기 때문입니다.</p><p>사실 생애최초 특별공급으로 배정된 세대수도 그리 많지 않기 때문에 소득 기준을 확인하는 추첨제까지 진행되어야 하므로 바로 이전에 진행되었던 다른 주택청약의 59 제곱미터 주택에 대한 특별공급의 경쟁률은 8대 1 이었던 점을 가정하여 당첨 가능성이 없다고 바라보았기에 일반공급 1순위도 신청하려고 했습니다. 그런데, 특별공급 신청결과를 보니 배정 세대수보다 신청자가 적었기 때문에 1인 가구 기준의 추첨 단계를 진행할 필요가 없이 사실 상 당첨이 된 상태가 되었습니다. 따라서, 일반공급 1순위 신청은 필요가 없으므로 증빙해야할 서류만 제대로 준비하면 됩니다.</p><blockquote><p>특별공급에 신청하더라도 일반공급에 중복으로 신청할 순 있습니다. 단, 동일 세대에서 중복 청약은 불가능하므로 세대 구성원에게 신청 여부를 사전에 공유해야합니다.</p></blockquote><h4 id="생애최초-특별공급-주의사항" tabindex="-1">생애최초 특별공급 주의사항 <a class="header-anchor" href="#생애최초-특별공급-주의사항" aria-label="Permalink to &quot;생애최초 특별공급 주의사항&quot;">​</a></h4><p>생애최초 특별공급에 당첨되면 서류 검증 과정에서 부적격 처리되더라도 생애최초 특별공급 기회는 당첨 즉시 사라지므로 앞으로 신청할 수 없습니다. 세대주가 만 60세를 넘었더라도 현재 거주중인 세대 주택을 <code>부모가 공동 명의로 보유중이라면</code> 주택을 소유한 세대 구성원인 부모 모두 <code>만 60세가 넘어야</code> 합니다. 부모의 과거 부동산 소유 이력이 명확하지 않다면 <a href="https://www.iros.go.kr/index.jsp" target="_blank" rel="noreferrer">인터넷등기소</a>에서 <code>부동산소유현황</code>을 조회해보는 것이 좋습니다.</p><p>🔥 생애최초 특별공급은 등본 상 세대구성원 전원이 과거에 주택을 소유한 이력이 없어야 합니다. 🔥 주택 공동 명의 여부와 주택 소유자의 만 60세 여부를 확인하지 않은 것은 신청자 본인 책임이 됩니다.</p><p>서류 심사 시 제출하는 모든 서류는 주민등록번호 뒷자리가 포함되어야하며 재직증명서 또는 근로소득원천징수 영수증과 같은 일부 서류는 복사본이 아닌 원본이어야하므로 모집공고와 서류 제출에 대한 안내를 토대로 사업주체(견본 주택)에 반드시 문의하는게 좋습니다.</p><blockquote><p>모집공고와 홈페이지에 추가로 공유된 서류제출 안내에 기재된 내용이 다른 부분과 정확한 발급 기준이 기재되지 않아 애매한 부분도 있었습니다.</p></blockquote><h4 id="생애최초-특별공급-시-1인가구" tabindex="-1">생애최초 특별공급 시 1인가구? <a class="header-anchor" href="#생애최초-특별공급-시-1인가구" aria-label="Permalink to &quot;생애최초 특별공급 시 1인가구?&quot;">​</a></h4><p>민영주택청약 모집공고 상 저는 일반공급 1순위 무주택세대구성원이면서 혼인을 하지 않은 <code>1인 가구</code>에 해당되므로 추첨제로 청약이 가능합니다. 1인 가구 중 단독세대인 경우와 단독세대가 아닌 자로 나누어지는데 현재 부모님과 함께 거주중이며 <code>주민등록표등본 상 직계존속과 함께 등재되어 단독세대가 아닌 자</code>가 되므로 전용면적 60 제곱미터를 넘는 주택에도 신청할 수 있습니다. 따라서, 모집공고 기준에서 가장 작은 주택면적인 70 제곱미터로 신청했습니다.</p><p>🔥 세대분리를 위해 임대차계약을 통해 <code>단독세대를 구성했다면 60 제곱미터 이하 주택에만 신청할 수 있어</code> 부적격 대상이되므로 주의해야합니다.</p><blockquote><p>만 30세를 넘어서 독립하지 않고 부모님 집에 거주하는 <a href="https://www.joongang.co.kr/article/25328304" target="_blank" rel="noreferrer">캥거루 족</a>이 단독세대가 아닌 자에 해당합니다.</p></blockquote><h4 id="생애최초-특별공급-시-5개년도-소득세-납부-증빙" tabindex="-1">생애최초 특별공급 시 5개년도 소득세 납부 증빙 <a class="header-anchor" href="#생애최초-특별공급-시-5개년도-소득세-납부-증빙" aria-label="Permalink to &quot;생애최초 특별공급 시 5개년도 소득세 납부 증빙&quot;">​</a></h4><p>생애최초 특별공급에 당첨되었다면 5개년도에 대한 소득세 납부를 증빙할 수 있는 서류를 준비해야합니다. 한 직장에 5년 동안 근무했다면 <code>직인 날인이 포함된 근로소득원천징수영수증</code>을 한번에 요구할 수 있지만 이직 사유가 있다면 해당 년도는 <code>근로소득자용 소득금액증명원</code>을 인터넷으로 발급하는 것이 편할 수 있습니다. 이때, 5개년도는 연속적일 필요가 없으므로 5년 동안의 소득세 납부 내역만 증명할 수 있으면 됩니다.</p><p>🔥 근로소득원천징수영수증은 팩스 또는 복사본이 아닌 원본으로 제출해야하며 주민등록번호 뒷자리는 반드시 포함해야합니다. 🔥 저의 경우 재직중인 회사에서 받은 근로소득원천징수영수증 중 일부가 <code>직인날인이 포함된 복사본</code>으로 되어있어 소득금액증명원으로 대체했습니다.</p><h4 id="생애최초-특별공급-시-자격기준-증빙서류" tabindex="-1">생애최초 특별공급 시 자격기준 증빙서류 <a class="header-anchor" href="#생애최초-특별공급-시-자격기준-증빙서류" aria-label="Permalink to &quot;생애최초 특별공급 시 자격기준 증빙서류&quot;">​</a></h4><p>무주택세대구성원으로서 생애최초 특별공급에 신청하여 당첨되었다면, <code>주민등록표등본에 기재된 형제자매를 제외한 모든 세대구성원 기준의 증빙서류</code>가 필요로 합니다. 따라서, 저를 포함한 직계존속에 해당하는 아버지와 어머니에 대한 서류를 발급하여 제출해야 합니다. 간이과세자인 아버지는 사업자 등록증 사본을 발급해야하고 근로자인 어머니는 재직중인 회사에 (아파트 계약 사유로) 재직 증명서 발급을 요청해야 했습니다.</p><ul><li>직인 날인된 재직증명서(또는 사업자 등록증 사본)</li><li>과거 변동사항이 모두 기재된 <a href="https://www.gov.kr/portal/service/serviceInfo/PTR000050333" target="_blank" rel="noreferrer">건강보험자격득실확인서</a></li></ul><p>🔥 세대 구성원의 재직증명서는 주민등록번호 뒷자리가 포함되어야 하므로 아파트 계약 또는 주택공급 계약용으로 발급 요청하면 됩니다.</p><h4 id="생애최초-특별공급-시-소득-및-자산-기준-증빙서류" tabindex="-1">생애최초 특별공급 시 소득 및 자산 기준 증빙서류 <a class="header-anchor" href="#생애최초-특별공급-시-소득-및-자산-기준-증빙서류" aria-label="Permalink to &quot;생애최초 특별공급 시 소득 및 자산 기준 증빙서류&quot;">​</a></h4><p>1인 가구 추첨 단계없이 당첨된 상태이지만 소득 기준에 적합함은 증빙해야합니다. 따라서, 3인가구 기준의 <code>세대 월 평균소득이 160% 이하인 11,528,499원 보다 적음</code>을 서류로 증빙만하면 되며 생애최초 특별공급에 당첨된 자의 <code>모든 세대 구성원은 자격 및 소득 수준을 위한 서류를 발급해야</code>합니다. 소득 기준 증빙을 위해서 다음의 서류가 필요로 하는데 입주자모집공고가 7월 이전이라면, 간이과세자 기준에서 전년도 소득금액증명 발급은 불가능하기 때문에 <code>전전년도 소득금액증명으로 발급해야</code>합니다.</p><ul><li>직인 날인된 재직증명서 또는 사업자 등록증 사본</li><li>직인 날인된 전년도 근로소득원천징수영수증 또는 전년도(또는 전전년도) 소득금액증명</li><li>피부양 직계존속(아버지와 어머니)의 주민등록표 초본 (상세)</li></ul><p>🔥 소득 기준을 초과한 경우에도 모든 세대원의 부동산 자산가액 기준으로 3억 3100만원 이하를 증빙할 수 있으면 됩니다 🔥 자산 기준 증빙 시 요구되는 서류는 발급이 생각보다 복잡합니다.</p><blockquote><p>근로자라면 근로소득원천징수영수증에 기재된 총 급여, 그리고 간이과세자의 경우 소득금액증명에 포함된 소득금액을 12개월로 나누면 월 평균소득이 되며 모든 세대원의 월 평균소득을 합치면 됩니다. 서류 검증 시 검수자의 도움을 받아 청약자가 직접 계산하여 확인해보니 약 700만원으로 계산되었습니다.</p></blockquote><p>아무튼, 생애최초 특별공급으로 쉽게 당첨되어버려서 오히려 증빙해야하는 서류가 많아서 복잡했습니다. 미리 산출했던 소득 기준이 잘못될 가능성도 있기 때문에 걱정이 되었으나 미비 서류 요구없이(서류 심사 시 사업주체가 넘어가주는 부분도 있음) 아파트 공급 계약을 체결했습니다.</p><hr><h4 id="정당-계약-당첨자-공급계약체결-시-필요한-서류" tabindex="-1">정당 계약(당첨자 공급계약체결) 시 필요한 서류 <a class="header-anchor" href="#정당-계약-당첨자-공급계약체결-시-필요한-서류" aria-label="Permalink to &quot;정당 계약(당첨자 공급계약체결) 시 필요한 서류&quot;">​</a></h4><p>생애최초 특별공급 당첨에 대한 서류를 제출하고 적격 여부를 확인받아 접수 확인증을 받았다면, 정당 계약 시 필요한 서류는 아래와 같습니다.</p><ul><li>신분증 사본 (견본주택에서 복사)</li><li>공통 및 생애최초 특별공급 자격검증서류 접수 확인증</li><li>본인서명사실확인서 또는 인감 증명서(아파트 계약용)</li><li>분양대금, 발코니 확장 공사비에 대한 무통장 입금 영수증</li><li>인지세 납부를 위한 종이문서용 전자수입인지</li></ul><p>🔥 서류 제출 시 인감 증명서를 포함했으므로 인감도장만 챙기면 됩니다. 🔥 분양 대금, 발코니 확장 공사비 대한 납부 계좌가 상이함에 주의해야 합니다. 🔥 인지세는 계약 체결에 대한 공급 계약서를 받고나서 우체국에서 인지세를 구매하면 됩니다.</p><p>서류 심사 후 홈페이지 및 문자로 공유된 계약 안내문에는 무통장 입금 영수증이 필요하다고 되어있으나 별도로 확인하지는 않았고 견본주택에서 출력한 것을 토대로 계약서에 함께 동봉되었습니다. 그리고 유상 선택 옵션은 계약 체결 시 함께 진행하지 않고 별도 일정을 통해 진행한다고 안내받았습니다. 본 주택청약의 경우 계약금은 분양 대금의 5%이며 <code>1차 계약금은 500만원</code>이며 나머지 금액에 대해서는 계약 체결일 이후 30일 이내에 사업주체가 정해놓은 분양대금 계좌에 입금해야합니다.</p><blockquote><p>계약금 입금이 연체되더라도 당장 계약 해지가 되는 건 아니지만 약 15% 이상의 연체 이자가 발생합니다. 또한, 계약 체결 이후 분양권 해지 시 위약금은 분양 대금의 10% 인 점도 계약 시 주의사항으로 안내해줍니다.</p></blockquote><hr><h4 id="중도금-대출" tabindex="-1">중도금 대출 <a class="header-anchor" href="#중도금-대출" aria-label="Permalink to &quot;중도금 대출&quot;">​</a></h4><p>아파트 공급 계약을 체결하는 과정에서 상담 직원을 통해 중도금 대출은 아직 협의된 은행은 정해지지 않았으며 중도금 1차 납부일 기준 약 한달 전에 문자로 통지될 것이라고 안내를 받았습니다. 본 주택청약은 중도금 대출 무이자 조건이 포함되어있는데 사업주체가 협의해놓은 은행기관을 통해 집단 중도금 대출을 체결해야 합니다.</p><p>생애최초 특별공급으로 LTV 80% 이면서 비규제지역이므로 대출 한도는 중도금 60% 까지되며 <code>무이자 조건</code>으로 진행될 것 이므로 계약자로써 납부해야할 금액은 <a href="https://www.khug.or.kr/hug/web/ig/hp/ighp000001.jsp" target="_blank" rel="noreferrer">주택구입자금보증</a>으로 대출 금액의 연 0.13%에 해당하는 중도금 대출 <code>보증료</code>와 <code>인지세</code>입니다. 그리고 중도금 1차 납부일에 발코니 확장 공사비와 유상 선택 옵션에 대한 중도금은 직접 납부해야합니다.</p><p>🔥 정당 계약 시와는 다르게 중도금 대출 체결로 지정된 은행 통장을 통해 납부하게 됩니다. 🔥 사업주체가 이자상환액을 대신 납부하는 무이자 조건이라면 <a href="https://www.nts.go.kr/nts/cm/cntnts/cntntsView.do?mi=40608&amp;cntntsId=239020" target="_blank" rel="noreferrer">장기주택저당차입금 이자상환액 소득공제</a>를 받을 순 없습니다.</p><hr><h4 id="잔금대출" tabindex="-1">잔금대출 <a class="header-anchor" href="#잔금대출" aria-label="Permalink to &quot;잔금대출&quot;">​</a></h4><p>한국주택금융공사의 <a href="https://www.hf.go.kr/ko/sub01/sub01_02_01.do#" target="_blank" rel="noreferrer">디딤돌대출</a>을 DSR 40% 기준으로 받고나서 자금이 부족한 경우 <a href="https://www.hf.go.kr/ko/sub01/sub01_01_01.do" target="_blank" rel="noreferrer">보금자리론</a>으로 DTI 60%를 추가적으로 더 받을수도 있습니다. 그런데, 내집 마련을 위한 디딤돌 대출이 <code>2025년 7월부터 후취담보가 금지</code>가 되는 상태가 되어버리므로 입주자예정협의회를 통해 협약된 은행으로 후취담보 집단대출을 받아야만 합니다. 보금자리론 상품의 금리가 낮은 편은 아니기에 입주예정일 전에 대출 상담을 받아봐야 비교가 될 것 같습니다.</p><blockquote><p>생애최초특례구입자금보증으로 담보주택가격의 LTV 80%까지 대출을 받을 수 있어도 디딤돌 대출과 보금자리론의 대출 조건에 의해 대출이 불가능할 수 있습니다. 만약, 무주택 세대주 조건을 위해 세대분리를 하더라도 만 30세 이상 단독세대주가 된다면 대출 조건에 해당되지 않는 주택입니다.</p></blockquote><h4 id="취득세-및-국민주택채권-그리고-설정채권" tabindex="-1">취득세 및 국민주택채권 그리고 설정채권 <a class="header-anchor" href="#취득세-및-국민주택채권-그리고-설정채권" aria-label="Permalink to &quot;취득세 및 국민주택채권 그리고 설정채권&quot;">​</a></h4><p>중도금 6차 납부 후 중도금 대출 만기 일자인 입주예정일이 도래했다면 나머지 잔금 비용과 함께 중도금 대출 원리금 상환을 위해 잔금 대출을 받았을 것입니다. 잔금 대출에 대한 <code>설정채권</code> 비용과 부동산 소유권 이전 등기를 위한 <code>국민주택채권</code> 매입 그리고 분양 대금과 발코니 확자 공사비, 유상 선택옵션 금액을 모두 포한한 취득가액 기준으로 취득세(1%)와 지방교육세(0.1%)가 있습니다. 그리고 각 채권에 대한 인지세와 등기 수수료(증지대 및 재증명 등)도 필요하겠죠.</p><p>🔥 공동주택에 대한 농어촌특별세도 있지만 주거전용면적 기준 85제곱미터 이하 주택이므로 비과세입니다. 🔥 등기에 대한 비용은 <a href="https://xn--989a00af8jnslv3dba.com/%EB%93%B1%EA%B8%B0%EB%B9%84%EC%9A%A9" target="_blank" rel="noreferrer">부동산 계산기</a>로 계산해볼 수 있습니다.</p><h5 id="생애최초-취득세-감면" tabindex="-1">생애최초 취득세 감면 <a class="header-anchor" href="#생애최초-취득세-감면" aria-label="Permalink to &quot;생애최초 취득세 감면&quot;">​</a></h5><p>본 민영주택 청약은 실거주 의무가 없는 조건이지만 생애최초 주택을 구입한 자에게 주어지는 <a href="https://www.banksalad.com/articles/25%EB%85%84-%EC%83%9D%EC%95%A0%EC%B5%9C%EC%B4%88-%EC%A3%BC%ED%83%9D-%EC%B7%A8%EB%93%9D%EC%84%B8-%EA%B0%90%EB%A9%B4-%ED%98%9C%ED%83%9D-%EC%B4%9D%EC%A0%95%EB%A6%AC" target="_blank" rel="noreferrer">취득세 감면 혜택</a>을 받고자 하는 경우라면 <code>실거주 의무 3년</code>을 지자체에서 적용합니다. 저는 투자 목적이 아닌 실거주를 위한 아파트 분양이기 때문에 취득세 감면을 받는게 좋다고 생각되며, 생애최초 취득세 감면 혜택을 받고나서 매매 시 발생하는 취득세 감면 금액 추징과 가산세보다 매매를 통해 이루어지는 금전적인 이득이 더 크다고 하므로 일단 <code>무조건 취득세 감면 혜택을 받는 것이 나은 선택</code>이라고 말합니다.</p><p>감사합니다.</p>',50)])])}const u=a(l,[["render",c]]);export{b as __pageData,u as default};
